-- ============================================
-- LUMA — Thème 6 : MOYEN 2/3 x4 — Régler un conflit sur les factures
-- ============================================


update scenarios set content = '{"characters": {"roommate": "ton/ta coloc"}, "start_node": "n1", "nodes": {"n1": {"speaker": "roommate", "text": "Hey, I noticed the electricity bill was way higher this month. Can we talk about it?", "text_fr": "Hé, j''ai remarqué que la facture d''électricité était bien plus élevée ce mois-ci. On peut en parler ?", "choices": [{"text": "Sure, I''ve noticed that too, let''s figure out why.", "text_fr": "Bien sûr, je l''ai remarqué aussi, comprenons pourquoi.", "next": "n2"}, {"text": "Yeah, I was actually going to bring that up too.", "text_fr": "Ouais, j''allais justement en parler aussi.", "next": "n2"}]}, "n2": {"speaker": "roommate", "text": "I think it might be because of the AC running all day while I work from home.", "text_fr": "Je pense que c''est peut-être à cause de la clim qui tourne toute la journée pendant que je travaille de chez moi.", "choices": [{"text": "That makes sense — should we split it differently to reflect that?", "text_fr": "Ça se comprend — on devrait le partager différemment pour refléter ça ?", "next": "n3"}, {"text": "I get it, though I do feel like the current 50/50 split isn''t quite fair then.", "text_fr": "Je comprends, même si je sens que le partage 50/50 actuel n''est pas tout à fait juste alors.", "next": "n3"}]}, "n3": {"speaker": "roommate", "text": "That''s fair. What if I paid a bit more, since I''m using it more during the day?", "text_fr": "C''est juste. Et si je payais un peu plus, vu que je l''utilise plus pendant la journée ?", "choices": [{"text": "That sounds reasonable — maybe a 60/40 split?", "text_fr": "Ça semble raisonnable — peut-être un partage 60/40 ?", "next": "n4"}, {"text": "I appreciate you offering that, thank you for understanding.", "text_fr": "J''apprécie que tu proposes ça, merci de comprendre.", "next": "n4"}]}, "n4": {"speaker": "roommate", "text": "60/40 sounds fair to me, given the AC usage difference.", "text_fr": "60/40 me semble juste, vu la différence d''utilisation de la clim.", "choices": [{"text": "Great, let''s do that going forward.", "text_fr": "Super, faisons ça à partir de maintenant.", "next": "n5"}]}, "n5": {"speaker": "roommate", "text": "Should we also set some general rules, like turning off lights when not needed?", "text_fr": "On devrait aussi fixer des règles générales, comme éteindre les lumières quand c''est pas nécessaire ?", "choices": [{"text": "Good idea, that could help keep costs down for both of us.", "text_fr": "Bonne idée, ça pourrait aider à réduire les coûts pour nous deux.", "next": "n6"}, {"text": "Definitely, and maybe set the AC to a slightly higher temperature too?", "text_fr": "Carrément, et peut-être régler la clim un peu plus haut aussi ?", "next": "n6"}]}, "n6": {"speaker": "roommate", "text": "Sounds like a solid plan. I really appreciate you being so understanding about this.", "text_fr": "Ça a l''air d''un bon plan. J''apprécie vraiment que tu sois si compréhensif là-dessus.", "choices": [{"text": "Of course, communication makes this so much easier.", "text_fr": "Bien sûr, la communication rend tout ça bien plus facile.", "next": "n7"}]}, "n7": {"speaker": "roommate", "text": "Agreed. Let''s check in again next month to see if the new split feels fair.", "text_fr": "D''accord. Refaisons le point le mois prochain pour voir si le nouveau partage semble juste.", "choices": [{"text": "Sounds good, I''m glad we could sort this out calmly.", "text_fr": "Ça marche, je suis content qu''on ait pu régler ça calmement.", "next": "end_resolved"}]}, "end_resolved": {"speaker": "roommate", "text": "Me too. This is exactly the kind of teamwork that makes living together work.", "text_fr": "Moi aussi. C''est exactement ce genre de travail d''équipe qui fait que la colocation fonctionne.", "end": true, "ending_label": "Conflit de factures résolu à l''amiable 💡🤝"}}}'::jsonb, is_playable = true
where title = 'Régler un conflit sur les factures'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));
